/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CoverageStatusSchema, CoverageStatus, CoverageSurfaceSchema, CoverageSurface, CoverageEntrySchema, CoverageEntry, CoverageInventorySchema, CoverageInventory (+4 more)
 * depends    —
 * used by    src/mechanics/coverage/build-inventories, src/mechanics/coverage/index, src/mechanics/doctor/tower-probes, src/mechanics/kernel/load, src/mechanics/registry/build, src/mechanics/sdk-graph/invariants (+1 more)
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { z } from 'zod'

/** How a surface entry relates to the mechanics graph. */
export const CoverageStatusSchema = z.enum([
  'modeled',
  'unmodeled',
  'out_of_scope',
  'historical',
])
export type CoverageStatus = z.infer<typeof CoverageStatusSchema>

export const CoverageSurfaceSchema = z.enum([
  'sheet',
  'save',
  'wiki',
  'sdk-module',
])
export type CoverageSurface = z.infer<typeof CoverageSurfaceSchema>

/**
 * One inventory row. Complete iff graphNodeIds nonempty OR coverageStatus is
 * an explicit unknown/out-of-scope/historical marker (not a silent gap).
 */
export const CoverageEntrySchema = z.object({
  id: z.string().min(1),
  surface: CoverageSurfaceSchema,
  label: z.string().min(1),
  graphNodeIds: z.array(z.string()).default([]),
  coverageStatus: CoverageStatusSchema,
  reason: z.string().optional(),
  sources: z.array(z.string()).default([]),
  reviewedAt: z.string().optional(),
  /** Optional link to formula-coverage fidelity when surface is sdk-module. */
  formulaFidelity: z.enum(['confirmed', 'inferred', 'partial', 'missing']).optional(),
})
export type CoverageEntry = z.infer<typeof CoverageEntrySchema>

export const CoverageInventorySchema = z.object({
  version: z.literal(1),
  surface: CoverageSurfaceSchema,
  generatedAt: z.string().optional(),
  notes: z.string().optional(),
  entries: z.array(CoverageEntrySchema),
})
export type CoverageInventory = z.infer<typeof CoverageInventorySchema>

export function isExplicitUnknown(status: CoverageStatus): boolean {
  return status === 'unmodeled' || status === 'out_of_scope' || status === 'historical'
}

export function isCoverageComplete(entry: CoverageEntry): boolean {
  if ((entry.graphNodeIds?.length ?? 0) > 0) return true
  return isExplicitUnknown(entry.coverageStatus)
}

export function findSilentGaps(inventory: CoverageInventory): CoverageEntry[] {
  return inventory.entries.filter(e => !isCoverageComplete(e))
}

export function coverageStatusCounts(inventory: CoverageInventory): Record<string, number> {
  const counts: Record<string, number> = {}
  for (const e of inventory.entries) {
    counts[e.coverageStatus] = (counts[e.coverageStatus] ?? 0) + 1
  }
  return counts
}
